export function getColourThisImageBase(unitId: string): string {
  return `/images/primary/${unitId}`;
}

/** Games menu URL for the same theme/unit as the Colour This game */
export function getColourThisGamesMenuHref(unitId: string): string {
  const dot = unitId.indexOf(".");
  if (dot < 0) return "/primary-school";
  const grade = unitId.slice(0, dot);
  const rest = unitId.slice(dot + 1);
  if (grade === "2") return `/primary-school/grade-2/theme-${rest}/games`;
  if (grade === "3") {
    const unitNum = rest === "10" ? "10" : String(Number(rest));
    return `/primary-school/grade-3/unit-${unitNum}/games`;
  }
  if (grade === "4") return `/primary-school/grade-4/unit-${rest}/games`;
  return "/primary-school";
}

